import React from "react";
import { graphql, Link, type HeadFC } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Layout from "../components/Layout";
import SEO from "../components/seo";

const AboutPage: React.FC = () => {
  const { t } = useTranslation("about");

  return (
    <Layout activeNav="about">
      <div style={{ paddingTop: "var(--space-10)", paddingBottom: "var(--space-10)" }}>
        <div className="cc-container" style={{ paddingTop: "var(--space-8)" }}>
          <div className="section-label">
            <span className="num">00</span>
            <span className="rule" />
            <span className="name">{t("sectionName")}</span>
          </div>
          <h1 className="text-h1" style={{ maxWidth: 640 }}>{t("title")}</h1>
          <p className="text-lg-body" style={{ maxWidth: 560, marginTop: "var(--space-4)" }}>{t("sub")}</p>
        </div>

        <div className="section-divider cc-container" />

        <div className="cc-container">
          {/* Story */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-16 items-start">
            <div>
              <h2 className="text-h2">{t("storyTitle")}</h2>
              <div className="flex flex-col gap-4 mt-5">
                {(t("storyParagraphs", { returnObjects: true }) as string[]).map((p, i) => (
                  <p key={i} className="text-base-body">{p}</p>
                ))}
              </div>
            </div>
            <div className="flex flex-col gap-6">
              {(t("values", { returnObjects: true }) as Array<{ title: string; text: string }>).map((v) => (
                <div key={v.title} className="cc-card">
                  <h3 className="text-h3">{v.title}</h3>
                  <p className="text-base-body mt-3">{v.text}</p>
                </div>
              ))}
            </div>
          </div>

          {/* Why us */}
          <div style={{ marginTop: "var(--space-10)" }}>
            <h2 className="text-h2">{t("whyTitle")}</h2>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 mt-8">
              {(t("whyItems", { returnObjects: true }) as Array<{ title: string; text: string }>).map((item) => (
                <div key={item.title} className="cc-card">
                  <h3 className="text-h3">{item.title}</h3>
                  <p className="text-base-body mt-3">{item.text}</p>
                </div>
              ))}
            </div>
          </div>

          {/* CTA */}
          <div style={{
            textAlign: "center", marginTop: "var(--space-10)",
            padding: "var(--space-9) var(--space-6)",
            background: "var(--bg-surface)", border: "1px solid var(--border-2)",
            borderRadius: "var(--radius-lg)",
          }}>
            <h2 className="text-h2">{t("ctaTitle")}</h2>
            <p className="text-lg-body" style={{ maxWidth: 500, margin: "var(--space-4) auto 0" }}>{t("ctaSub")}</p>
            <Link to="/contact/" className="btn-primary" style={{ marginTop: "var(--space-6)", display: "inline-flex" }}>
              {t("ctaBtn")}
              <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><path d="M5 12h14M12 5l7 7-7 7" /></svg>
            </Link>
          </div>
        </div>
      </div>
    </Layout>
  );
};

export default AboutPage;

export const Head: HeadFC = ({ data, location }: any) => (
  <SEO
    data={data.allDataJson.nodes[0]}
    title="About - Code Crafted"
    description="Code Crafted is a custom software studio based in Quebec, Canada. We build operational software for SMBs in English, French, and Spanish."
    language={data.locales?.edges?.[0]?.node?.language}
    originalPath={location.pathname}
    pageSchemaType="AboutPage"
    schemaType="Organization"
  />
);

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges { node { ns data language } }
    }
    allDataJson {
      nodes {
        companyName address city province country postalCode
        phone email instagram facebook linkedin whatsapp url
        founder { name jobTitle sameAs }
      }
    }
  }
`;
